import{_ as a,o as s,c as i,j as e,a as o,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const r="/assets/templates-list.CGm1JyI9.png",l="/assets/template-create.DZRqHm8n.png",d="/assets/template-editor.BPcJ-IOX.png",h="/assets/template-field-type.CTDE4aHA.png",p="/assets/template-field.DeW3gNec.png",c="/assets/template-field-order.CnTkzdjW.png",g="/assets/templates-more-menu.zrxMzHVS.png",T=JSON.parse('{"title":"Working with Templates","description":"","frontmatter":{},"headers":[],"relativePath":"templates.md","filePath":"templates.md"}'),m={name:"templates.md"};function u(f,t,w,b,v,y){return s(),i("div",null,[...t[0]||(t[0]=[e("h1",{id:"working-with-templates",tabindex:"-1"},[o("Working with Templates "),e("a",{class:"header-anchor",href:"#working-with-templates","aria-label":'Permalink to "Working with Templates"'},"​")],-1),e("p",null,"Templates define which metadata you collect for each asset, and they're the key to adding assets to your Elevator instance. You can create as many templates as you like, and you can nest templates within other templates.",-1),e("iframe",{src:"https://www.youtube.com/embed/S54sySvBRRk",title:"Creating Templates and Assets in Elevator",style:{width:"100%","aspect-ratio":"16 / 9",border:"0"},allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1),n('<h2 id="the-templates-list" tabindex="-1">The Templates List <a class="header-anchor" href="#the-templates-list" aria-label="Permalink to &quot;The Templates List&quot;">​</a></h2><p>Open the <strong>Admin</strong> menu and choose <strong>Edit Templates</strong>, or choose <strong>Templates</strong> in the sidebar on any admin page. You need the <strong>Edit Templates</strong> or <strong>Administer Instance</strong> permission on the instance. See <a href="/permissions.html#permission-levels">Permission Levels</a>.</p><p><img src="'+r+'" alt="The Templates list, showing one template named Simple"></p><p>The list shows each template&#39;s ID, name, and when it was created and last modified. Type in <strong>Search templates</strong> to narrow the list. Click a template&#39;s name to edit it.</p><p>Each row&#39;s <strong>⋮</strong> menu has <strong>Edit</strong>, <strong>Duplicate</strong>, <strong>Reindex</strong>, and <strong>Delete</strong>. See <a href="#duplicating-reindexing-and-deleting">Duplicating, Reindexing, and Deleting</a>.</p><h2 id="creating-a-template" tabindex="-1">Creating a Template <a class="header-anchor" href="#creating-a-template" aria-label="Permalink to &quot;Creating a Template&quot;">​</a></h2><ol><li>On the Templates list, click <strong>Create Template</strong>.</li><li>Enter a <strong>Name</strong> that makes clear what the template is for.</li><li>Optionally, set the <a href="#advanced-options">Advanced Options</a>.</li><li>Add fields with <strong>+ Add Field</strong>. See <a href="#adding-a-field">Adding a Field</a>.</li><li>Click <strong>Save</strong>.</li></ol><p>The new template starts with an empty <strong>Fields</strong> section. Here, the template is named &quot;Photographs&quot; and is ready for its first field.</p><p><img src="'+l+'" alt="A new Photographs template with the Name filled in, an empty Fields section, and the Add Field and Save buttons"></p><p><strong>Save</strong> keeps you in the editor, so you can go on making changes. The sidebar shows when the template was last saved, and &quot;No unsaved changes&quot; once everything is saved. <strong>Cancel</strong> returns to the Templates list.</p><h2 id="advanced-options" tabindex="-1">Advanced Options <a class="header-anchor" href="#advanced-options" aria-label="Permalink to &quot;Advanced Options&quot;">​</a></h2><p>Click <strong>Advanced options</strong> below the template&#39;s name to show these settings. Elevator sets sensible defaults for them.</p><p><img src="'+d+'" alt="The template editor, with Advanced options expanded and the Field order lists in the sidebar"></p><h3 id="hide-from-add-new-asset-menu" tabindex="-1">Hide from &#39;Add new asset&#39; menu <a class="header-anchor" href="#hide-from-add-new-asset-menu" aria-label="Permalink to &quot;Hide from &#39;Add new asset&#39; menu&quot;">​</a></h3><p>When on, this template doesn&#39;t appear in the list of templates when creating new assets, but it&#39;s still available for editing existing assets. This is useful for templates you want to retire without removing their assets.</p><h3 id="index-for-searching" tabindex="-1">Index for searching <a class="header-anchor" href="#index-for-searching" aria-label="Permalink to &quot;Index for searching&quot;">​</a></h3><p>When off, this template isn&#39;t indexed for searching at all. Assets using this template can only be reached by their unique identifier, or by links from other assets. This is meant for &quot;join&quot; templates: templates that connect one asset to another with some descriptive data, but have no value on their own.</p><h3 id="include-in-public-search-results" tabindex="-1">Include in public search results <a class="header-anchor" href="#include-in-public-search-results" aria-label="Permalink to &quot;Include in public search results&quot;">​</a></h3><p>Sometimes you want to add assets but keep them out of public search results. For example, if this template is meant to be nested within other templates rather than stand on its own, turn this off.</p><h3 id="recursive-index-depth" tabindex="-1">Recursive index depth <a class="header-anchor" href="#recursive-index-depth" aria-label="Permalink to &quot;Recursive index depth&quot;">​</a></h3><p>When a template uses a <strong>Related Asset</strong> field to point to other assets, Elevator&#39;s search engine also indexes those related values. Choose <strong>None</strong>, <strong>Shallow</strong>, or <strong>Deep</strong>.</p><p>For example, suppose a template lists classrooms, and each classroom points to a &quot;building&quot; asset through a Related Asset field. To make a search for a building&#39;s name return every classroom in it, choose <strong>Shallow</strong>. If each building also points to a &quot;campus&quot; asset, <strong>Deep</strong> lets a search for the campus return all of its classrooms.</p><h3 id="show-collection-name-on-asset-page" tabindex="-1">Show collection name on asset page <a class="header-anchor" href="#show-collection-name-on-asset-page" aria-label="Permalink to &quot;Show collection name on asset page&quot;">​</a></h3><p>Adds the asset&#39;s collection to the asset page, so viewers can click it and browse every asset in that collection. Choose <strong>Off</strong>, <strong>Bottom</strong> (with the asset&#39;s other fields), or <strong>Top</strong> (as a breadcrumb).</p><h3 id="show-template-name-on-asset-page" tabindex="-1">Show template name on asset page <a class="header-anchor" href="#show-template-name-on-asset-page" aria-label="Permalink to &quot;Show template name on asset page&quot;">​</a></h3><p>Templates usually matter only to administrators and curators. If you want viewers to see and browse by template, this adds the asset&#39;s template to the asset page, so viewers can click it and browse every asset that uses it. Choose <strong>Off</strong>, <strong>Bottom</strong>, or <strong>Top</strong>, the same as for the collection name.</p><h2 id="adding-a-field" tabindex="-1">Adding a Field <a class="header-anchor" href="#adding-a-field" aria-label="Permalink to &quot;Adding a Field&quot;">​</a></h2><p>Each field in a template appears as a card in the <strong>Fields</strong> section. Click <strong>+ Add Field</strong> to add one, then set:</p><ul><li><strong>Field type</strong>: what kind of data the field holds, such as Text, Date, or Upload. See <a href="/field-types.html">Types of Fields</a>.</li><li><strong>Label</strong>: the name viewers see for this field.</li><li><strong>Field data (JSON)</strong>: settings for the field, shown only for field types that use them. Elevator fills it with sample JSON when you choose the type. If the JSON isn&#39;t valid, the box shows <strong>Invalid JSON</strong> and <strong>Save</strong> stays disabled until you fix it.</li></ul><p>The field type is the dropdown on the left of the card. For a title, choose <strong>Text</strong> and enter &quot;Title&quot; in the label box beside it. Click <strong>+ Add Field</strong> again for each additional field.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>There&#39;s no special &quot;title&quot; field. The first field in a template&#39;s <strong>Viewer</strong> order becomes the asset&#39;s title. See <a href="#field-order">Field Order</a>.</p></div><p><img src="'+h+'" alt="The field type dropdown open on a field labeled Title, showing Text selected and other types including Text Area and Date"></p><p>To remove a field, click its trash icon and confirm. Any data already saved in that field will no longer be visible or editable.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>When adding an asset, template fields left empty aren&#39;t displayed, so it&#39;s fine to have &quot;sometimes&quot; fields in a template.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Even file attachments are a type of field within a template. Don&#39;t forget to add an <strong>Upload</strong> field to your template so that you can add files to assets.</p></div><h3 id="field-options" tabindex="-1">Field Options <a class="header-anchor" href="#field-options" aria-label="Permalink to &quot;Field Options&quot;">​</a></h3><p>Click <strong>Options</strong> on a field&#39;s card to show its settings. The expand button next to <strong>Field order</strong> opens or closes the options on every card at once.</p><p><img src="'+p+'" alt="The options for a Text field named Title"></p><h4 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h4><ul><li><strong>Display on asset page</strong>: whether viewers see this field on the asset page. Some fields may be for internal use only.</li><li><strong>Display in preview</strong>: whether this field appears in the asset preview, which is used in search results, in drawers, and in related asset views. After changing this, <a href="#reindexing">reindex</a> the template.</li></ul><h4 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h4><ul><li><strong>Required</strong>: when on, an asset can&#39;t be saved until this field has a value.</li><li><strong>Allow multiple</strong>: when on, curators can add more than one value. For example, an item might need several dates.</li><li><strong>Attempt autocomplete</strong>: when on, the field suggests values as curators type, drawn from other assets that use the same template.</li><li><strong>Show tooltip</strong>: when on, enter <strong>Tooltip text</strong> to help curators adding assets. It can explain what belongs in the field, or how to format it.</li></ul><h4 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h4><ul><li><strong>Searchable</strong>: whether this field is indexed for searching. If a field is likely to hold data of low relevance, such as numbers without context, turn this off.</li><li><strong>Direct search</strong>: whether this field appears in <strong>Advanced Search</strong> as a field that can be searched on its own.</li><li><strong>Click to search</strong>: makes the field&#39;s value a link that starts a new search. <strong>Global</strong> searches every field for that value. <strong>Field-specific</strong> searches only this field.</li></ul><h4 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h4><ul><li><strong>Field Title</strong>: the field&#39;s internal name, which field-specific searches use. Elevator creates it from the label, such as <code>title_1</code>. To change it, click the pencil icon. It may contain only lowercase letters, numbers, underscores, and hyphens, and no two fields in a template can share one. Changing a field title can break saved data.</li></ul><h2 id="field-order" tabindex="-1">Field Order <a class="header-anchor" href="#field-order" aria-label="Permalink to &quot;Field Order&quot;">​</a></h2><p>Each template has two field orders:</p><ul><li><strong>Editor</strong>: the order curators see when adding or editing an asset.</li><li><strong>Viewer</strong>: the order viewers see on the asset page. The first field in this order is the asset&#39;s title.</li></ul><p>To change an order, use either of these:</p><ul><li>Choose <strong>Editor</strong> or <strong>Viewer</strong> next to <strong>Field order</strong> above the field cards, then drag cards by their handles. Dragging changes the order you chose.</li><li>Drag a field&#39;s name in the sidebar&#39;s <strong>Editor</strong> or <strong>Viewer</strong> list.</li></ul><p>In this example, <strong>Viewer</strong> is selected above the cards. &quot;Title&quot; is first in the sidebar&#39;s <strong>Viewer</strong> list, so its value will become each asset&#39;s title. The template also has a <strong>Text Area</strong> field labeled &quot;Description&quot; and a <strong>Date</strong> field labeled &quot;Date taken&quot;.</p><p><img src="'+c+'" alt="The Photographs template with Title, Description, and Date taken fields, Viewer order selected, and Title first in both sidebar lists"></p><p>Then click <strong>Save</strong>. If you moved a field that appears in previews, <a href="#reindexing">reindex</a> the template.</p><h2 id="duplicating-reindexing-and-deleting" tabindex="-1">Duplicating, Reindexing, and Deleting <a class="header-anchor" href="#duplicating-reindexing-and-deleting" aria-label="Permalink to &quot;Duplicating, Reindexing, and Deleting&quot;">​</a></h2><p><img src="'+g+'" alt="Templates page with the more actions menu open revealing choices to edit, duplicate, reindex, or delete"></p><p>These actions are in each template&#39;s <strong>⋮</strong> menu on the Templates list, and each asks you to confirm.</p><h3 id="duplicating" tabindex="-1">Duplicating <a class="header-anchor" href="#duplicating" aria-label="Permalink to &quot;Duplicating&quot;">​</a></h3><p>You may want a &quot;base&quot; template and a more detailed version of it. Create the base template, choose <strong>Duplicate</strong> to copy it, and then add the extra fields to the copy.</p><h3 id="reindexing" tabindex="-1">Reindexing <a class="header-anchor" href="#reindexing" aria-label="Permalink to &quot;Reindexing&quot;">​</a></h3><p>Some template changes require Elevator to reindex every asset that uses the template. The template editor doesn&#39;t start a reindex when you save, so choose <strong>Reindex</strong> after any of these changes:</p><ul><li>Turning <strong>Display in preview</strong> on or off for a field.</li><li>Changing the <strong>Field Title</strong> of a field that appears in previews.</li><li>Moving a field that appears in previews.</li></ul><p>Reindexing also covers any related templates. For large sets of assets, it can take a few minutes to finish.</p><h3 id="deleting" tabindex="-1">Deleting <a class="header-anchor" href="#deleting" aria-label="Permalink to &quot;Deleting&quot;">​</a></h3><p>Deleting a template causes assets that use it to display incorrectly, and it can&#39;t be undone. <strong>Use with caution!</strong></p>',65)])])}const q=a(m,[["render",u]]);export{T as __pageData,q as default};
